span.p:
First setup and IPC creation
004845DD call sub_4511E0
// Calls the first setup helper; EAX receives its status.
004845E2 mov ecx, eax
// Moves the status into ECX as the this pointer for the next call.
004845E4 call sub_452470
// Creates the named mutex and IPC sections before SCM registration.
004845E9 test eax, eax
// Tests the setup result for zero.
004845EB je loc_48498D
// Jumps to the failure path when setup returns zero.

Second setup path
004845F1 call sub_451240
// Calls the second initialization helper.
004845F6 mov ecx, eax
// Passes its result to the next setup call in ECX.
004845F8 call sub_452B20
// Runs the second setup path and creates more engine state.
004845FD test eax, eax
// Checks the second setup result for zero.
004845FF je loc_48498D
// Jumps to the same failure path on zero.

SCM dispatch table
00484605 lea eax, [esp+0x20]
// Computes the address of the SCM service table on the stack.
00484609 mov dword ptr [esp+0x20], 0x82B3C4
// Stores the HTTPDebuggerPro service name pointer.
00484611 push eax
// Pushes the service table pointer for the SCM call.
00484612 mov dword ptr [esp+0x28], 0x484440
// Stores the ServiceMain pointer at 0x484440.
0048462A call dword ptr [0x74F074]
// Calls StartServiceCtrlDispatcherA to hand control to the SCM.
